const __L = [];
let __s;
while ((__s = readLine()) !== null) __L.push(__s);
const T = __L.join(' ').split(/\s+/).filter((x) => x.length).map(Number);
const n = T[0], target = T[1];
const a = T.slice(2, 2 + n);
let i = 0, j = n - 1, cnt = 0;
while (i < j) {
  const s = a[i] + a[j];
  if (s < target) i++;
  else if (s > target) j--;
  else if (a[i] === a[j]) {
    const m = j - i + 1;
    cnt += (m * (m - 1)) / 2;
    break;
  } else {
    const x = a[i], y = a[j];
    let ci = 0, cj = 0;
    while (a[i] === x) { ci++; i++; }
    while (a[j] === y) { cj++; j--; }
    cnt += ci * cj;
  }
}
console.log(String(cnt));

