import java.util.*;
import java.io.*;

public class Main {
    static StreamTokenizer st;

    static long nl() throws IOException {
        st.nextToken();
        return (long) st.nval;
    }

    public static void main(String[] args) throws IOException {
        st = new StreamTokenizer(new BufferedInputStream(System.in));
        int n = (int) nl();
        long target = nl();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nl();
        int i = 0, j = n - 1;
        long cnt = 0;
        while (i < j) {
            long s = a[i] + a[j];
            if (s < target) i++;
            else if (s > target) j--;
            else if (a[i] == a[j]) {
                long m = j - i + 1;
                cnt += m * (m - 1) / 2;
                break;
            } else {
                long x = a[i], y = a[j];
                long ci = 0, cj = 0;
                while (a[i] == x) { ci++; i++; }
                while (a[j] == y) { cj++; j--; }
                cnt += ci * cj;
            }
        }
        System.out.println(cnt);
    }
}

