#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    long long target;
    scanf("%d %lld", &n, &target);
    vector<long long> a(n);
    for (auto &v : a) scanf("%lld", &v);
    int i = 0, j = n - 1;
    long long cnt = 0;
    while (i < j) {
        long long s = a[i] + a[j];
        if (s < target) i++;
        else if (s > target) j--;
        else if (a[i] == a[j]) {
            long long m = j - i + 1;
            cnt += m * (m - 1) / 2;
            break;
        } else {
            long long x = a[i], y = a[j], ci = 0, cj = 0;
            while (a[i] == x) { ci++; i++; }
            while (a[j] == y) { cj++; j--; }
            cnt += ci * cj;
        }
    }
    printf("%lld\n", cnt);
}
